for run in adapt_ontask_finger_seed17_ckpt500000 adapt_ontask_finger_seed18_ckpt500000 adapt_ontask_finger_seed19_ckpt500000 adapt_ontask_finger_seed20_ckpt500000 adapt_ontask_finger_seed21_ckpt500000 adapt_ontask_finger_seed22_ckpt500000 adapt_ontask_finger_seed23_ckpt500000 adapt_ontask_finger_seed24_ckpt500000 adapt_q1uzs0_finger_seed17_ckpt500000 adapt_q1uzs0_finger_seed18_ckpt500000 adapt_q1uzs0_finger_seed19_ckpt500000 adapt_q1uzs0_finger_seed20_ckpt500000 adapt_q1uzs0_finger_seed21_ckpt500000 adapt_q1uzs0_finger_seed22_ckpt500000 adapt_q1uzs0_finger_seed23_ckpt500000 adapt_q1uzs0_finger_seed24_ckpt500000 adapt_q1uzs1_finger_seed17_ckpt500000 adapt_q1uzs1_finger_seed18_ckpt500000 adapt_q1uzs1_finger_seed19_ckpt500000 adapt_q1uzs1_finger_seed20_ckpt500000 adapt_q1uzs1_finger_seed21_ckpt500000 adapt_q1uzs1_finger_seed22_ckpt500000 adapt_q1uzs1_finger_seed23_ckpt500000 adapt_q1uzs1_finger_seed24_ckpt500000 adapt_scratchvf_finger_seed17_ckpt0 adapt_scratchvf_finger_seed18_ckpt0 adapt_scratchvf_finger_seed19_ckpt0 adapt_scratchvf_finger_seed20_ckpt0 adapt_scratchvf_finger_seed21_ckpt0 adapt_scratchvf_finger_seed22_ckpt0 adapt_scratchvf_finger_seed23_ckpt0 adapt_scratchvf_finger_seed24_ckpt0; do
